struct vector3d
{
	float x;
	float y;
	float z;
};

struct BeachData
{
	char pad[208];
	bool bdir;
	char tail[323];
};

class game
{
	char pad[552];
	int beach_id;

public:
	int get_beach_id() { return beach_id; }
};

class board_controller
{
public:
	vector3d GetForwardDir();
};

class ScoringManager
{
public:
	enum ATTRIBUTE
	{
		ATTR_DIST_LIP
	};

	void AddTrick(int trick);
	void UpdateLastTrick(ATTRIBUTE attribute, float value, int flags = 0);
};

enum
{
	TRICK_TAKEOFF = 84,
	TRICK_FADETAKEOFF = 85,
	TRICK_FAKIETAKEOFF = 86,
	TRICK_FAKIEFADETAKEOFF = 87
};

extern BeachData BeachDataArray[];
extern game *g_game_ptr;

class kellyslater_controller
{
	char pad0[3408];
	board_controller my_board_controller;
	char pad1[936];
	ScoringManager my_scoreManager;

public:
	float Lip_Distance();
	void DetermineTakeoffType(bool weak);
};

void kellyslater_controller::DetermineTakeoffType(bool weak)
{
	bool left_wave = BeachDataArray[g_game_ptr->get_beach_id ()].bdir;
	vector3d board_vec = my_board_controller.GetForwardDir();

	//  Which direction is the board facing.
	if ((board_vec.x > 0 && left_wave) || (board_vec.x < 0 && !left_wave))  //  Faced towards tube.
	{
		if (board_vec.z > 0)  //  backwards
			my_scoreManager.AddTrick(TRICK_FAKIEFADETAKEOFF);
		else
			my_scoreManager.AddTrick(TRICK_FADETAKEOFF);
	}
	else
	{
		if (board_vec.z > 0)  //  backwards
			my_scoreManager.AddTrick(TRICK_FAKIETAKEOFF);
		else
			my_scoreManager.AddTrick(TRICK_TAKEOFF);
	}

	my_scoreManager.UpdateLastTrick(ScoringManager::ATTR_DIST_LIP, weak?100.0f:Lip_Distance());
}
